/// Concatenate two `Vec<i32>` values, returning `a` followed by `b`.
///
/// Properties satisfied for all inputs:
/// - `c.len() == a.len() + b.len()`
/// - For all `i < a.len()`: `c[i] == a[i]`
/// - For all `i < b.len()`: `c[a.len() + i] == b[i]`
///
/// Termination:
/// - Each loop iterates over a finite range (`0..a.len()` and `0..b.len()`),
///   so the function always terminates.
pub fn append_array(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    let a_len = a.len();
    let b_len = b.len();

    // Pre-allocate exact capacity so pushes don't reallocate.
    let mut c: Vec<i32> = Vec::with_capacity(a_len + b_len);

    // Copy elements of `a` in order.
    for i in 0..a_len {
        c.push(a[i]);
    }

    // Copy elements of `b` in order, appended after all of `a`.
    for i in 0..b_len {
        c.push(b[i]);
    }

    c
}